const t = key => (TR[key] || [key, key])[LANG === "en" ? 1 : 0];
const tf = (key, ...args) => args.reduce((s, a, i) => s.replaceAll(`{${i}}`, a), t(key));

// tradução de etiquetas de execução guardadas (o valor gravado é sempre o PT)
const TAG_EN = {
  "A correr (target)": "Running (target)", "A correr (Jenkins)": "Running (Jenkins)",
  "A guardar logs": "Saving logs", "Executado": "Executed", "Falhou": "Failed"
};
const tagDisplay = tag => (LANG === "en" && TAG_EN[tag]) ? TAG_EN[tag] : tag;
